const st = built.stat;
console.log(`built n=${n} fresh=${st.fresh} kept=${st.kept} missing=${st.missing.length} queries ok=${st.ok}/${st.queries} retried=${st.retried} ${((Date.now() - t0) / 1000).toFixed(1)}s`);
const body = JSON.stringify({ m3u: built.m3u, state: built.state, stat: { n, fresh: st.fresh, kept: st.kept } });
const p = await signed("POST", "/_push/live", body);
console.log("push", p.status, p.status === 200 ? p.text : "");
import fs from "node:fs";
fs.writeFileSync("yt_summary.txt", `n=${n} fresh=${st.fresh} kept=${st.kept} ok=${st.ok}/${st.queries} push=${p.status}`);
process.exit(p.status === 200 ? 0 : 1);
